__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"COURSES",{enumerable:!0,get:function(){return n}});var t=r(d[0]),N=r(d[1]);const n={[N.SAFE_KIND.id]:N.SAFE_KIND,[t.EARNING_ONLINE.id]:t.EARNING_ONLINE}},806,[1124,807]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"SAFE_KIND",{enumerable:!0,get:function(){return t}});const t={id:"safe-kind",title:"Safe & Kind Online",pace:"daily",tracks:[{id:"explorers",title:"Explorers",ages:"6\u20139",lessons:[{id:"private-stuff",title:"Some Things Stay Private",emoji:"\ud83d\udd12",cards:[{type:"read",text:"Some things about you are private. Your home address, your school's name, and your passwords are private."},{type:"read",text:"Private things stay with you and your guardian. Don't type them anywhere unless your guardian says it's okay."},{type:"read",text:"In games, you can use a fun nickname. A nickname keeps your real name safe."},{type:"scenario",text:"You are playing a game. A box pops up: 'Type your home address to get a free prize!'",choices:[{text:"Type your address fast so you get the prize.",best:!1,why:"It's fine to want a prize, but your address is private, so it stays with you."},{text:"Close the box and tell your guardian.",best:!0,why:"Yes! Your guardian can help you check if it's real."},{text:"Type your friend's address instead.",best:!1,why:"Your friend's address is private too, so it's kind to keep it safe."}]},{type:"check",question:"Which one is private?",options:["Your favorite color","Your password","Your favorite animal"],answer:1},{type:"talk",text:"With your guardian, sort these into 'okay to share' and 'keep private': your favorite food, your home address, your password, your favorite song."}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Privacy & Safety)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"Google Be Internet Awesome: Share with Care",url:"https://beinternetawesome.withgoogle.com/en_us/educators"}]},{id:"kind-words",title:"Kind Words Make Good Days",emoji:"\ud83d\udc9b",cards:[{type:"read",text:"Words on a screen can make someone smile or feel sad. A real person reads what you send."},{type:"read",text:"If someone sends you something mean, you don't have to answer. Show your guardian."},{type:"read",text:"On OurDot, you can tap the report button to let a grown-up know something wasn't kind."},{type:"scenario",text:"Your cousin posts a drawing. Another kid in the family chat writes, 'That looks silly.'",choices:[{text:"Write something mean back to the kid.",best:!1,why:"Feeling upset is normal, but mean words usually make things worse."},{text:"Say something kind to your cousin, and tell a guardian what happened.",best:!0,why:"Your kind words help your cousin, and a guardian can help fix the problem."},{text:"Pretend you didn't see it.",best:!1,why:"It's easy to look away, but a kind word from you could help your cousin feel better."}]},{type:"check",question:"Someone sends you a mean message. What is a good first step?",options:["Send a mean message back","Show your guardian","Keep it a secret"],answer:1},{type:"talk",text:"Ask your guardian: What is one kind message we could send to someone in our family today?"}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Cyberbullying & Online Harms)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"Google Be Internet Awesome: It's Cool to Be Kind",url:"https://beinternetawesome.withgoogle.com/en_us/educators"},{title:"UKCIS Education for a Connected World (2020), Online bullying",url:"https://www.gov.uk/government/publications/education-for-a-connected-world"}]},{id:"ask-a-grown-up",title:"When in Doubt, Ask",emoji:"\ud83d\ude4b",cards:[{type:"read",text:"Sometimes you see something online that feels confusing, weird, or yucky. That happens to everyone."},{type:"read",text:"When something feels off, stop and tell a trusted grown-up. Telling is always the right thing to do."},{type:"read",text:"On OurDot, the guardian line is always open. You can message your guardian anytime."},{type:"scenario",text:"You are watching a video, and something comes on that gives you a funny feeling in your tummy.",choices:[{text:"Keep watching to see what happens.",best:!1,why:"Being curious is normal, but you never have to keep watching something that feels bad."},{text:"Close it and tell your guardian how it made you feel.",best:!0,why:"Great choice! Telling a grown-up helps you feel better and stay safe."},{text:"Hide the tablet so no one finds out.",best:!1,why:"Feeling worried is okay, and your grown-ups would rather help you than have you deal with it alone."}]},{type:"check",question:"Who can you ask when something online feels weird?",options:["A trusted grown-up, like your guardian","Nobody","Someone you don't know in a game"],answer:0},{type:"talk",text:"Together, name three trusted grown-ups you can go to. Practice saying, 'I saw something that felt weird.'"}],sources:[{title:"Google Be Internet Awesome: When in Doubt, Talk It Out",url:"https://beinternetawesome.withgoogle.com/en_us/educators"},{title:"NCMEC NetSmartz resources",url:"https://us.missingkids.org/netsmartz/resources"},{title:"AAP / HealthyChildren: The 5 Cs of Media Use",url:"https://healthychildren.org/English/family-life/Media/Pages/kids-and-screen-time-how-to-use-the-5-cs-of-media-guidance.aspx"}]},{id:"tricky-messages",title:"Tricky Messages",emoji:"\ud83d\udd75\ufe0f",cards:[{type:"read",text:"Some messages try to trick you. They might say you won a prize or that you must click right now."},{type:"read",text:"Tricky messages often try to rush you. When a message says hurry, that's your sign to slow down."},{type:"read",text:"If you're not sure, don't click. Ask your guardian to look with you."},{type:"scenario",text:"A message says: 'You won 1,000 free coins! Click this link in 1 minute or lose them!'",choices:[{text:"Click fast before time runs out!",best:!1,why:"Lots of kids would want free coins, but a hurry message is a sign of a trick."},{text:"Show it to your guardian before clicking anything.",best:!0,why:"Smart! Your guardian can help you check if it's real."},{text:"Send the link to your friends so they get coins too.",best:!1,why:"Sharing is a kind idea, but the trick could reach your friends too."}]},{type:"check",question:"A message says 'Hurry, click now!' What should you do?",options:["Click right away","Slow down and ask your guardian","Click it two times"],answer:1},{type:"talk",text:"Ask your guardian to tell you about a tricky message they once got. How did they know it was a trick?"}],sources:[{title:"Google Be Internet Awesome: Don't Fall for Fake",url:"https://beinternetawesome.withgoogle.com/en_us/educators"},{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Privacy & Safety)",url:"https://www.commonsense.org/education/scope-and-sequence"}]},{id:"screens-rest",title:"Screens Need Rest Too",emoji:"\ud83c\udf19",cards:[{type:"read",text:"Screens can be fun. Your body and brain also need outside play, reading, and lots of sleep."},{type:"read",text:"Sleep helps you grow and feel good. At night, devices sleep best outside your bedroom."},{type:"read",text:"When screen time is done, you can say, 'Bye for now!' and pick something new to do."},{type:"scenario",text:"It's almost bedtime, and you are in the middle of a game.",choices:[{text:"Hide under the blanket and keep playing.",best:!1,why:"It's hard to stop a fun game, but your body needs sleep to feel good tomorrow."},{text:"Find a stopping point, then put the device in its nighttime spot.",best:!0,why:"Nice! Your game will still be there tomorrow, and you'll be rested."},{text:"Get upset and beg for one more hour.",best:!1,why:"Feeling sad to stop is normal. Calmly asking for two minutes to finish works better."}]},{type:"check",question:"Where is a good place for devices to sleep at night?",options:["Under your pillow","Outside your bedroom","In your bed"],answer:1},{type:"talk",text:"With your guardian, pick a nighttime spot for devices and plan one fun no-screen thing to do before bed."}],sources:[{title:"AAP / HealthyChildren: Where We Stand: Screen Time",url:"https://healthychildren.org/English/family-life/Media/Pages/Where-We-Stand-TV-Viewing-Time.aspx"},{title:"AAP / HealthyChildren: The 5 Cs of Media Use",url:"https://healthychildren.org/English/family-life/Media/Pages/kids-and-screen-time-how-to-use-the-5-cs-of-media-guidance.aspx"}]},{id:"stop-think-share",title:"Stop, Think, Share",emoji:"\ud83d\udcf8",cards:[{type:"read",text:"Before you post a picture, stop and think. Is it kind? Is everyone in it okay with it?"},{type:"read",text:"Ask before you share a photo of someone else. Everyone gets to choose about their own picture."},{type:"read",text:"OurDot has a pause-before-posting check. It gives you a moment to think before anything goes out."},{type:"scenario",text:"You took a funny picture of your brother making a silly face. You want to post it.",choices:[{text:"Post it now. It's so funny!",best:!1,why:"It is funny, but your brother may not want everyone to see it."},{text:"Ask your brother if it's okay first.",best:!0,why:"Yes! Asking shows respect, and he gets to choose."},{text:"Post it and tell him later.",best:!1,why:"Telling him is good, but asking first is fairer."}]},{type:"check",question:"Before you post a photo of a friend, you should...",options:["Ask your friend if it's okay","Add a funny caption","Post it fast"],answer:0},{type:"talk",text:"Look at a few family photos together. Ask your guardian: Which ones would we share, and which ones would we keep just for us?"}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Digital Footprint & Identity)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"Google Be Internet Awesome: Share with Care",url:"https://beinternetawesome.withgoogle.com/en_us/educators"}]}]},{id:"navigators",title:"Navigators",ages:"10\u201312",lessons:[{id:"strong-and-smart",title:"Strong Passwords, Smart Clicks",emoji:"\ud83d\udd11",cards:[{type:"read",text:"A strong password is long and hard to guess. Three or four random words strung together work well."},{type:"read",text:"Keep passwords between you and your guardian, not your friends. Even good friends can share one by accident."},{type:"read",text:"Some fake messages look real and try to get your password. Be careful with any surprise message that asks you to log in."},{type:"scenario",text:"A message that looks like it's from your game says: 'Your account will be deleted! Log in here to keep it.'",choices:[{text:"Log in through the link quickly.",best:!1,why:"Wanting to save your account makes sense, but links in surprise messages can lead to fake pages."},{text:"Skip the link, open the game app yourself to check, and show your guardian.",best:!0,why:"Exactly. Going to the real app yourself keeps you away from fake pages."},{text:"Reply and ask if it's real.",best:!1,why:"Questioning it is a good instinct, but replying tells the sender your account is active."}]},{type:"check",question:"Which is the strongest password?",options:["password123","Your name and birthday","purple-tractor-moon-socks","1234"],answer:2},{type:"talk",text:"With your guardian, check that your accounts have strong passwords, and turn on two-step login wherever it's offered."}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Privacy & Safety)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"Google Be Internet Awesome: Secure Your Secrets",url:"https://beinternetawesome.withgoogle.com/en_us/educators"}]},{id:"be-an-upstander",title:"Be an Upstander",emoji:"\ud83e\udd1d",cards:[{type:"read",text:"An upstander is someone who helps when they see meanness. You don't have to be loud to do it."},{type:"read",text:"Small things count: send the person a kind message, don't share the mean post, and tell a trusted adult."},{type:"read",text:"On OurDot, you can report a mean message. Reporting is helping, not tattling."},{type:"scenario",text:"In a group chat, people start joking about a classmate's haircut. The classmate is in the chat.",choices:[{text:"Add a laughing emoji so you fit in.",best:!1,why:"Wanting to fit in is normal, but the emoji can make the classmate feel worse."},{text:"Send the classmate something kind, and tell a trusted adult.",best:!0,why:"That's what an upstander does. Your kindness and an adult's help both matter."},{text:"Leave the chat and forget about it.",best:!1,why:"Stepping away is okay, but checking on the classmate helps even more."}]},{type:"check",question:"Which one is an upstander move?",options:["Sharing the mean post","Sending a kind message to the person being picked on","Laughing along"],answer:1},{type:"talk",text:"Ask your guardian: Have you ever seen someone being picked on? What did you do, or what do you wish you had done?"}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Cyberbullying & Online Harms)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"UKCIS Education for a Connected World (2020), Online bullying",url:"https://www.gov.uk/government/publications/education-for-a-connected-world"},{title:"Google Be Internet Awesome: It's Cool to Be Kind",url:"https://beinternetawesome.withgoogle.com/en_us/educators"}]},{id:"red-flags",title:"Spotting Red Flags",emoji:"\ud83d\udea9",cards:[{type:"read",text:"OurDot only has people your family invited. Other apps and games can have people you don't know."},{type:"read",text:"Red flags: someone asks you to keep a secret, asks for photos, offers gifts, or wants you to move to a different app."},{type:"read",text:"If you see a red flag, stop chatting, block them, and tell your guardian. Telling is always the right move."},{type:"scenario",text:"In an online game, a player you don't know says, 'You're really good. Let's chat on another app where no one can see.'",choices:[{text:"Go to the other app. They seem nice.",best:!1,why:"Compliments feel good, but asking you to move somewhere private is a red flag."},{text:"Say no, block them, and tell your guardian.",best:!0,why:"Exactly right. You stopped it and got help."},{text:"Keep chatting in the game, but don't go to the other app.",best:!1,why:"Saying no to the app was good, but the safest move is to stop and tell a grown-up."}]},{type:"check",question:"Which one is a red flag?",options:["Someone says 'good game'","Someone asks you to keep your chat a secret","Someone asks what level you're on"],answer:1},{type:"talk",text:"With your guardian, make a plan: What words will you use to tell them if someone online makes you uncomfortable?"}],sources:[{title:"NCMEC NetSmartz resources (online enticement, gaming)",url:"https://us.missingkids.org/netsmartz/resources"},{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Relationships & Communication)",url:"https://www.commonsense.org/education/scope-and-sequence"}]},{id:"your-digital-trail",title:"Your Digital Trail",emoji:"\ud83d\udc63",cards:[{type:"read",text:"Everything you post leaves a trail, like footprints in sand. Some footprints stay a long time."},{type:"read",text:"Anyone can take a screenshot, so a post can be saved and shared even after you delete it."},{type:"read",text:"OurDot's pause-before-posting check asks: Would I be okay if my grandparent, my teacher, or my future self saw this?"},{type:"scenario",text:"You're annoyed at a friend and type a post about them. The pause-before-posting check pops up.",choices:[{text:"Skip the check and post it.",best:!1,why:"Being annoyed is real, but a post can last longer than the feeling."},{text:"Delete the post, then talk to your friend or a guardian about what happened.",best:!0,why:"Great choice. Talking can fix things, and a post usually doesn't."},{text:"Post it now and delete it later.",best:!1,why:"Deleting later won't help if someone already took a screenshot."}]},{type:"check",question:"Why should you think before posting?",options:["Posts can be saved and shared, even if you delete them","Posts disappear right away","Nobody ever reads posts"],answer:0},{type:"talk",text:"Ask your guardian to search their own name online with you. Talk about what you find and how it got there."}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Digital Footprint & Identity)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"UKCIS Education for a Connected World (2020), Online reputation",url:"https://www.gov.uk/government/publications/education-for-a-connected-world"}]},{id:"real-or-fake",title:"Is It Real?",emoji:"\ud83d\udd0d",cards:[{type:"read",text:"Not everything online is true. Photos can be edited, and AI can make pictures and voices that look and sound real."},{type:"read",text:"Before you believe or share something, ask: Who made this? How do they know? Can I find it somewhere I trust?"},{type:"read",text:"When you're not sure, it's okay to say 'I don't know yet' and ask an adult to check with you."},{type:"scenario",text:"A friend sends a video of a shark swimming down a city street during a storm. It says 'SHARE THIS NOW!'",choices:[{text:"Share it right away so everyone sees!",best:!1,why:"Amazing videos are fun to share, but rushing is how fake stuff spreads."},{text:"Check whether trusted news sites are reporting it before you share.",best:!0,why:"Smart! Checking first helps stop fake stuff from spreading."},{text:"Believe it, since lots of people shared it.",best:!1,why:"Lots of shares can feel convincing, but being popular doesn't make something true."}]},{type:"check",question:"What's a good question to ask about something you see online?",options:["How many likes does it have?","Who made this, and how do they know?","Is it funny?"],answer:1},{type:"talk",text:"Find a surprising headline or picture together, then work with your guardian to figure out whether it's real."}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Information & Media Literacy)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"Google Be Internet Awesome: Don't Fall for Fake",url:"https://beinternetawesome.withgoogle.com/en_us/educators"},{title:"UKCIS Education for a Connected World (2020), Managing online information",url:"https://www.gov.uk/government/publications/education-for-a-connected-world"}]},{id:"finding-balance",title:"Finding Your Balance",emoji:"\u2696\ufe0f",cards:[{type:"read",text:"Screens are great for games, friends, and learning. Balance means making room for sleep, moving, and people too."},{type:"read",text:"Notice how you feel after screen time. Happy and calm, or tired and grumpy? Your feelings are good clues."},{type:"read",text:"Kids your age need lots of sleep. Charging devices outside your bedroom helps you get it."},{type:"scenario",text:"You planned to play for 30 minutes, but an hour has gone by and you feel kind of grumpy.",choices:[{text:"Keep going. Maybe the next round will feel better.",best:!1,why:"That feeling is really common, and many games are built to make stopping hard."},{text:"Take a break: stretch, grab a snack, or go outside.",best:!0,why:"Nice! Noticing your feelings and taking a break is a real skill."},{text:"Blame your sibling for distracting you.",best:!1,why:"Feeling grumpy is okay, but a break will help more than blaming."}]},{type:"check",question:"What's a good clue that it's time for a screen break?",options:["You feel tired or grumpy","You just started","You're having fun with family"],answer:0},{type:"talk",text:"With your guardian, make or update a family media plan: when screens are on, when they're off, and where devices sleep at night."}],sources:[{title:"AAP / HealthyChildren: The 5 Cs of Media Use",url:"https://healthychildren.org/English/family-life/Media/Pages/kids-and-screen-time-how-to-use-the-5-cs-of-media-guidance.aspx"},{title:"AAP / HealthyChildren: Where We Stand: Screen Time",url:"https://healthychildren.org/English/family-life/Media/Pages/Where-We-Stand-TV-Viewing-Time.aspx"}]}]},{id:"trailblazers",title:"Trailblazers",ages:"13\u201317",lessons:[{id:"your-footprint-your-story",title:"Your Footprint, Your Story",emoji:"\ud83d\udc63",cards:[{type:"read",text:"What you post builds a picture of who you are. Schools, teams, and employers may look someday, and that can work in your favor."},{type:"read",text:"Your footprint isn't only about avoiding mistakes. Sharing your projects, interests, and kindness builds a story you're proud of."},{type:"read",text:"Check your privacy settings on every app and review old posts now and then. OurDot's pause-before-posting check is a built-in moment to ask, 'Is this the me I want to show?'"},{type:"scenario",text:"You're about to post a video roasting a teacher. It's funny, and your friends would love it.",choices:[{text:"Post it. It's just a joke.",best:!1,why:"Wanting a laugh is normal, but jokes about real people can spread far beyond the audience you meant."},{text:"Share the laugh with friends in person, and post something you're proud of instead.",best:!0,why:"You keep the laugh and keep your footprint the way you want it."},{text:"Post it with your account set to private.",best:!1,why:"Private settings help, but anyone who can see a post can still screenshot it."}]},{type:"check",question:"Which best describes a digital footprint?",options:["Only the posts you make public","Everything you share, or that others share about you, which can last","Posts from the last week","Your step count"],answer:1},{type:"talk",text:"Ask your guardian: Is there anything from your teen years you're glad never went online? What would you want people to find about you today?"}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Digital Footprint & Identity)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"UKCIS Education for a Connected World (2020), Online reputation",url:"https://www.gov.uk/government/publications/education-for-a-connected-world"}]},{id:"check-before-you-share",title:"Check Before You Share",emoji:"\ud83d\udcf0",cards:[{type:"read",text:"Posts built to make you angry or shocked are easy to share without thinking. A strong reaction is your cue to slow down."},{type:"read",text:"Good fact-checking means leaving the post: open a new tab and see what trusted sources say about the claim and the person behind it."},{type:"read",text:"AI can make realistic images, voices, and videos. Look for the original source, not just the clip."},{type:"scenario",text:"A post claims your school is canceling prom because of a rule change. It's going viral with a screenshot of an 'email from the principal.'",choices:[{text:"Share it so everyone knows.",best:!1,why:"Wanting to warn friends is kind, but screenshots are easy to fake."},{text:"Check the school's official channels or ask a teacher before sharing.",best:!0,why:"Going to the original source is exactly how fact-checkers work."},{text:"Comment that it's fake.",best:!1,why:"You might be right, but checking first makes your comment accurate and helpful."}]},{type:"check",question:"What's the best first move when a post makes you really angry?",options:["Share it fast","Pause and check who made it and what trusted sources say","Comment in all caps","Assume it's true because it's popular"],answer:1},{type:"talk",text:"Pick a news story you saw this week. With your guardian, trace it back to the original source. Did the details change along the way?"}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Information & Media Literacy)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"UKCIS Education for a Connected World (2020), Managing online information",url:"https://www.gov.uk/government/publications/education-for-a-connected-world"},{title:"Google Be Internet Awesome: Don't Fall for Fake",url:"https://beinternetawesome.withgoogle.com/en_us/educators"}]},{id:"green-flags-red-flags",title:"Green Flags, Red Flags",emoji:"\ud83d\udcac",cards:[{type:"read",text:"Healthy relationships, online or off, feel respectful and safe. You can say no, take your time replying, and keep your own friends."},{type:"read",text:"Red flags include constantly checking where you are, demanding your passwords, pressuring you for photos, or getting angry when you don't reply fast."},{type:"read",text:"Pressure isn't love. If something feels off, talk to a trusted adult. On OurDot, the guardian line is always open."},{type:"scenario",text:"Someone you're dating says, 'If you really cared, you'd share your location with me 24/7 and give me your password.'",choices:[{text:"Share both so they don't get upset.",best:!1,why:"Wanting to keep the peace makes sense, but caring about someone doesn't mean giving up your privacy."},{text:"Calmly say you're not comfortable with that, and talk to a trusted adult about how it felt.",best:!0,why:"Setting a boundary and getting support are both healthy moves."},{text:"Secretly check their phone to see what they're hiding.",best:!1,why:"Feeling unsure is real, but snooping adds to the problem instead of fixing it."}]},{type:"check",question:"Which one is a green flag?",options:["They respect it when you say no","They want all your passwords","They get angry if you don't reply within 5 minutes"],answer:0},{type:"talk",text:"Ask your guardian: How can you tell whether a friend or partner respects you? What's one boundary that matters to you?"}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Relationships & Communication)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"UKCIS Education for a Connected World (2020), Online relationships",url:"https://www.gov.uk/government/publications/education-for-a-connected-world"}]},{id:"pressure-and-threats",title:"When Someone Pressures or Threatens You",emoji:"\ud83d\udedf",cards:[{type:"read",text:"Sometimes a person online, who may not be who they say they are, pressures someone for a private photo, then threatens to share it unless they pay or send more. This is called sextortion, and it is never the young person's fault."},{type:"read",text:"If it happens: stop replying, don't pay, block and report the account, and save the messages. Screenshot the chat, but never any images."},{type:"read",text:"Tell a trusted adult. On OurDot, the guardian line is always open. You can also report at NCMEC's CyberTipline: report.cybertip.org."},{type:"read",text:"NCMEC's Take It Down (takeitdown.ncmec.org) helps remove nude images taken when you were under 18. Your image stays on your device; only a digital fingerprint is shared."},{type:"scenario",text:"A new follower on another app sends Jordan flirty messages, then asks for a private photo. When Jordan says no, they write, 'Send one or I'll tell everyone you already did.'",choices:[{text:"Send a photo so they stop.",best:!1,why:"Wanting it to end is understandable, but giving in usually leads to more demands."},{text:"Stop replying, save the messages, block and report, and tell a trusted adult.",best:!0,why:"This is exactly the right plan, and it takes real courage."},{text:"Keep it secret and hope it goes away.",best:!1,why:"Many people freeze like this, but help works best when it starts early."}]},{type:"check",question:"If someone threatens to share a private image unless you pay, what should you do?",options:["Pay them so it ends","Stop replying, don't pay, save evidence, and tell a trusted adult","Delete everything and say nothing","Send a different photo"],answer:1},{type:"talk",text:"Ask your guardian: If I ever came to you with something embarrassing or scary from online, how would you react? Agree on a no-shame plan together."}],sources:[{title:"NCMEC Take It Down",url:"https://takeitdown.ncmec.org/"},{title:"OJJDP Sextortion Victim Resource Sheet",url:"https://ojjdp.ojp.gov/publications/sextortion-victim-resource-sheet.pdf"},{title:"NCMEC NetSmartz resources (sextortion)",url:"https://us.missingkids.org/netsmartz/resources"}]},{id:"calling-in-not-piling-on",title:"Calling In, Not Piling On",emoji:"\ud83d\udde3\ufe0f",cards:[{type:"read",text:"Online, it's easy to say things you'd never say face to face. Remembering there's a real person behind every name helps."},{type:"read",text:"When a pile-on starts, you can refuse to join, message the person being targeted privately, and report harmful posts."},{type:"read",text:"Report hate speech and threats every time. On OurDot, use the report button, and block anyone who targets you."},{type:"scenario",text:"A relative posts an opinion you strongly disagree with, and your cousins start mocking them in the comments.",choices:[{text:"Jump in with your best comeback.",best:!1,why:"Strong opinions are normal, but piling on usually hardens people instead of changing minds."},{text:"Skip the pile-on and, if you want, share your view respectfully or privately.",best:!0,why:"Disagreeing with respect keeps both the conversation and the relationship alive."},{text:"Screenshot it and post it somewhere else to mock them.",best:!1,why:"Feeling frustrated is fair, but spreading it multiplies the harm."}]},{type:"check",question:"Which is an upstander move during a pile-on?",options:["Adding a comeback","Privately checking on the person being targeted","Sharing screenshots","Liking the meanest reply"],answer:1},{type:"talk",text:"Ask your guardian: How do we disagree respectfully as a family? Have you ever changed your mind because someone was kind about it?"}],sources:[{title:"Common Sense Education: Digital Citizenship Scope & Sequence (Cyberbullying & Online Harms)",url:"https://www.commonsense.org/education/scope-and-sequence"},{title:"UKCIS Education for a Connected World (2020), Online bullying",url:"https://www.gov.uk/government/publications/education-for-a-connected-world"}]},{id:"your-attention-your-choice",title:"Your Attention, Your Choice",emoji:"\ud83d\udd0b",cards:[{type:"read",text:"Many apps are designed to keep you scrolling, with endless feeds, streaks, and constant notifications. Knowing that puts you back in charge."},{type:"read",text:"Teens need plenty of sleep. Charging your phone outside your room at night is one of the simplest ways to protect it."},{type:"read",text:"Try a check-in: How do I feel after using this app? Turn off the notifications you don't need, and keep the ones that matter."},{type:"scenario",text:"It's 11 p.m. You have a test tomorrow, and you keep refreshing your feed.",choices:[{text:"One more scroll, then sleep.",best:!1,why:"That loop is really common, but 'one more' often turns into an hour."},{text:"Put your phone on the charger outside your room and go to sleep.",best:!0,why:"That protects your sleep, which helps you tomorrow."},{text:"Switch to a different app instead.",best:!1,why:"A different app can feel like a break, but your brain still isn't resting."}]},{type:"check",question:"What's one simple way to protect your sleep?",options:["Keep your phone under your pillow","Charge your phone outside your bedroom","Turn the brightness down and keep scrolling","Keep your phone in bed as your alarm"],answer:1},{type:"talk",text:"With your guardian, look at your screen time report together, with no judgment. Each of you picks one change to try this week."}],sources:[{title:"AAP / HealthyChildren: The 5 Cs of Media Use",url:"https://healthychildren.org/English/family-life/Media/Pages/kids-and-screen-time-how-to-use-the-5-cs-of-media-guidance.aspx"},{title:"AAP / HealthyChildren: Where We Stand: Screen Time",url:"https://healthychildren.org/English/family-life/Media/Pages/Where-We-Stand-TV-Viewing-Time.aspx"},{title:"AAP Center of Excellence on Social Media and Youth Mental Health",url:"https://www.aap.org/en/patient-care/media-and-children/center-of-excellence-on-social-media-and-youth-mental-health/"}]}]}]}},807,[]);
