__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"EARNING_ONLINE",{enumerable:!0,get:function(){return t}});const t={id:"earning-online",title:"Earning Online, the Honest Way",blurb:"Real numbers, real rules and how to spot scams. Makers (10\u201317) learn with a guardian; Builders are for adults.",pace:"self",tracks:[{id:"makers",title:"Makers",ages:"10\u201317, always with a guardian",lessons:[{id:"m-what-earning-really-looks-like",title:"What earning online really looks like",emoji:"\ud83d\udd0d",cards:[{type:"read",text:"Lots of people try to earn money online, and most earn small amounts. In a 2022 Linktree survey, 68% of part-time creators made under $1,000 a year, and so did 46% of full-time creators."},{type:"read",text:"Video views are very lopsided. One study of YouTube found about 3% of channels got about 85% of all views, so the famous kids you see are the rare top, not the usual result."},{type:"read",text:"That's okay! A small, real business teaches planning, kindness to customers and handling money, even if it earns $20 instead of $20,000."},{type:"scenario",text:"A friend says a kid online made a million dollars selling slime, so you could too. What's the best way to think about it?",choices:[{text:"Plan on making a million dollars by summer.",best:!1,why:"Counting on the rarest result can leave you feeling like you failed when you didn't."},{text:"Try a small slime sale with your guardian and see what real customers will pay.",best:!0,why:"Starting small shows you real numbers without a big risk."},{text:"Give up, because only famous kids earn anything.",best:!1,why:"Small earnings are still real, and the skills you learn last."}]},{type:"check",question:"Why do we mostly hear about online sellers who got rich?",options:["Because most sellers get rich","Because rare big wins get shared and the many small results don't","Because small sellers aren't allowed to post"],answer:1},{type:"talk",text:"Ask your guardian: what's one small thing we could make or do together for someone, and what would count as a good first result?"}],sources:[{title:"Linktree 2022 Creator Report (via Techdirt)",url:"https://www.techdirt.com/2022/05/13/the-internet-has-opened-up-the-creator-economy-to-new-heights/"},{title:"B\xe4rtl (2018), YouTube channels, uploads and views",url:"https://opus.hs-offenburg.de/frontdoor/index/index/year/2018/docId/2616"}]},{id:"m-pick-a-first-business",title:"Choosing a first business with your guardian",emoji:"\ud83e\uddfa",cards:[{type:"read",text:"Great first businesses happen close to home with a guardian nearby: crafts, baked goods, pet care, yard help, reading buddies for younger kids, or reselling toys you've outgrown."},{type:"read",text:"Selling sites have age rules. Etsy requires users to be 18; 13- to 17-year-olds may only sell through a guardian's account with the guardian supervising, and kids under 13 can't use Etsy. Upwork freelancers must be 18."},{type:"read",text:"Federal law lets kids of any age babysit, do chores in private homes, or help in a non-hazardous business their own family owns. Your state may add rules, and the stricter rule always wins."},{type:"scenario",text:"You're 12 and want to sell bracelets online. What's the best first step?",choices:[{text:"Make your own Etsy account and say you're 18.",best:!1,why:"Fibbing about your age breaks the rules and can get the shop, and its money, shut down."},{text:"Sell through your guardian's account with them in charge, or start at a school or community craft fair.",best:!0,why:"This follows the rules and keeps a trusted adult in the loop."},{text:"Message strangers online and ask them to buy.",best:!1,why:"Reaching out to strangers isn't safe, and it isn't how good shops find customers."}]},{type:"check",question:"How can a 14-year-old sell on Etsy?",options:["Any way they like","Only through a guardian's account, with the guardian supervising","Never, under any circumstances"],answer:1},{type:"talk",text:"With your guardian, list three things you're good at, then pick one you could safely offer to family friends or neighbors."}],sources:[{title:"Etsy Terms of Use (age rules)",url:"https://www.etsy.com/legal/terms-of-use"},{title:"U.S. Dept. of Labor elaws: child labor FAQ",url:"https://webapps.dol.gov/elaws/faq/esa/flsa/026.htm"},{title:"Upwork: freelancer eligibility",url:"https://support.upwork.com/hc/en-us/articles/211067778"}]},{id:"m-money-basics",title:"Money basics: price, costs and records",emoji:"\ud83e\uddee",cards:[{type:"read",text:"Profit is what's left after costs. If a bracelet sells for $8 and the beads, string and bag cost $3, you keep $5 before any fees."},{type:"read",text:"Selling sites take a share too. Etsy charges $0.20 to list an item, 6.5% of the sale, and a payment-processing fee, so an $8 sale puts less than $8 in your pocket."},{type:"read",text:"Write down every sale and every cost the day it happens. If you earn $400 or more in a year working for yourself, you usually have to file a tax return, and your guardian can help with it."},{type:"scenario",text:"You sold 10 cookies for $2 each. The ingredients cost $8. How much did you earn?",choices:[{text:"$20",best:!1,why:"That's your sales; you still need to subtract what you spent."},{text:"$12",best:!0,why:"$20 in sales minus $8 in costs leaves $12 of profit."},{text:"$28",best:!1,why:"Costs get subtracted, not added."}]},{type:"check",question:"Why keep a record of every sale and cost?",options:["So you know your real profit and can answer tax questions","Because it makes things sell faster","It isn't needed if you're a kid"],answer:0},{type:"talk",text:"With your guardian, set up a simple money log with four columns: date, what happened, money in, money out."}],sources:[{title:"Etsy Fees & Payments Policy",url:"https://www.etsy.com/legal/fees/"},{title:"IRS Publication 929: tax rules for children and dependents",url:"https://www.irs.gov/publications/p929"}]},{id:"m-spot-scams",title:"Spotting scams and too-good offers",emoji:"\ud83d\udea9",cards:[{type:"read",text:"Fake jobs and 'business chances' are common. In 2024, people told the FTC they lost $750.6 million to business and job opportunity scams."},{type:"read",text:"Red flags: you have to pay to start, someone promises easy or guaranteed money, they rush you, or they want you to sign up your friends."},{type:"read",text:"Some companies mostly reward people for recruiting friends who also buy products. When FTC staff studied 70 of these companies' own income reports in 2024, most people made $1,000 a year or less, often before costs. Recruiting-style selling isn't allowed on OurDot."},{type:"scenario",text:"Someone online says: 'Pay $49 for a starter kit and earn $500 a week by getting your friends to join!' What do you do?",choices:[{text:"Pay fast before the deal ends.",best:!1,why:"Rushing you is a classic scam trick."},{text:"Ask your friends to join so you earn faster.",best:!1,why:"Pulling friends in can cost them money and hurt friendships."},{text:"Don't reply, and show your guardian.",best:!0,why:"A trusted adult can help you check it and report it if needed."}]},{type:"check",question:"Which one is a red flag?",options:["A shop that shows prices before you buy","Having to pay money before you can earn money","A neighbor who pays you after you walk their dog"],answer:1},{type:"talk",text:"Ask your guardian whether they've ever seen a 'get rich quick' offer, and how they could tell it wasn't real."}],sources:[{title:"FTC: reported fraud losses jump to $12.5 billion in 2024",url:"https://www.ftc.gov/news-events/news/press-releases/2025/03/new-ftc-data-show-big-jump-reported-losses-fraud-125-billion-2024"},{title:"FTC staff report analyzes 70 MLM income disclosure statements",url:"https://search.ftc.gov/business-guidance/blog/2024/09/ftc-staff-report-analyzes-70-mlm-income-disclosure-statements"},{title:"FTC: Multi-level marketing businesses and pyramid schemes",url:"https://consumer.ftc.gov/articles/multi-level-marketing-businesses-and-pyramid-schemes"}]},{id:"m-ads-say-ads",title:"Ads should say they're ads",emoji:"\ud83d\udce3",cards:[{type:"read",text:"When someone is paid, gets free stuff or earns money from a link, US rules say they must tell viewers clearly, right where the post is. Words like 'ad' or 'sponsored' work; hiding it in a bio or a pile of hashtags doesn't."},{type:"read",text:"The FTC says even 'affiliate link' isn't clear enough on its own, because many people don't know it means 'I get paid.' Plain words like 'I earn money if you buy through this link' are better."},{type:"read",text:"On OurDot, nobody under 18 posts ads or is shown ads. Learning the rules now helps you spot hidden ads everywhere else."},{type:"scenario",text:"A creator you like says 'This is the best headset ever!' and, way down in the description, writes #partner. What's going on?",choices:[{text:"It's just their opinion, nothing to notice.",best:!1,why:"A hidden tag hints at a paid deal you deserve to know about."},{text:"It may be a paid deal, so weigh the praise carefully.",best:!0,why:"Spotting hidden ads helps you make your own choices."},{text:"They must be lying about everything.",best:!1,why:"Paid creators can still be honest; the deal just should be shown clearly."}]},{type:"check",question:"Where should an ad disclosure go?",options:["Only in the profile bio","Right with the post, where it's easy to notice","At the very end, after lots of hashtags"],answer:1},{type:"talk",text:"With your guardian, look at three posts or videos and decide together: is this an ad? How can you tell?"}],sources:[{title:"FTC: Disclosures 101 for Social Media Influencers",url:"https://www.ftc.gov/business-guidance/resources/disclosures-101-social-media-influencers"},{title:"FTC: Endorsement Guides, What People Are Asking",url:"https://www.ftc.gov/business-guidance/resources/ftcs-endorsement-guides"}]},{id:"m-your-face-your-choice",title:"Your face, your choice, your money",emoji:"\ud83d\udee1\ufe0f",cards:[{type:"read",text:"Your name, face, school and town are yours to protect. YouTube requires users to be at least 13, anyone under 18 needs a guardian's okay, and YouTube may remove livestreams of kids under 16 when no adult is visible."},{type:"read",text:"Some states protect kids who appear in money-making videos. Since 2025, California requires part of the earnings to be saved in a trust for the child, and Minnesota bars kids under 14 from content creation work and lets anyone 13 or older ask for videos of them to be deleted."},{type:"read",text:"Kids usually can't sign binding contracts by themselves, so any deal with a company needs your guardian. If a stranger offers you a deal directly, stop and tell your guardian."},{type:"scenario",text:"A company messages you: 'We'll send you free shoes if you post about them. Let's keep this between us.' What's the best move?",choices:[{text:"Say yes. Free shoes!",best:!1,why:"Secret deals with strangers aren't safe, no matter the prize."},{text:"Don't reply, and show your guardian right away.",best:!0,why:"Being asked to keep secrets from your guardian is a big warning sign."},{text:"Ask for more free stuff first.",best:!1,why:"Bargaining keeps you talking to someone who has already asked for secrecy."}]},{type:"check",question:"Why does a guardian need to be part of any business deal for a kid?",options:["Kids usually can't sign binding contracts and deserve a trusted adult's protection","So the guardian can keep all the money","It's only a rule on weekends"],answer:0},{type:"talk",text:"Talk with your guardian about what you're comfortable sharing online and what you want kept private, even if sharing it could earn money."}],sources:[{title:"YouTube Child Safety Policy",url:"https://support.google.com/youtube/answer/2801999"},{title:"California SB 764 signed (Sen. Padilla)",url:"https://sd18.senate.ca.gov/news/california-governor-signs-senator-padilla-bill-updating-financial-protections-youth-content"},{title:"Minnesota Statutes 181A.13",url:"https://www.revisor.mn.gov/statutes/cite/181A.13"}]}]},{id:"builders",title:"Builders",ages:"18+",lessons:[{id:"b-honest-numbers",title:"The honest numbers",emoji:"\ud83d\udcca",cards:[{type:"read",text:"Platform income usually tops up a paycheck rather than replacing it. JPMorgan Chase Institute data found median monthly platform earnings under $1,000 in every sector except leasing, and the top 10% of sellers took 80% of selling earnings."},{type:"read",text:"Creating content has steep odds. In Linktree's 2022 survey, 46% of full-time creators earned under $1,000 a year and 12% earned over $50,000."},{type:"read",text:"Etsy's marketplace had about 5.6 million active sellers and $10.46 billion in sales in 2025, roughly $1,870 per seller per year before fees and costs. Sales are concentrated, so the typical shop likely earns less than that."},{type:"scenario",text:"A post says: 'I quit my job after three months of selling printables!' How should you use it?",choices:[{text:"Treat it as a likely outcome and plan to quit.",best:!1,why:"One story tells you nothing about the many people who tried and quietly stopped."},{text:"Run a small test with a spending cap and a time limit, and judge it by your own numbers.",best:!0,why:"A capped test gives you real data and limits the downside."},{text:"Write off online income entirely.",best:!1,why:"Modest extra income is realistic for many people; the hype is the problem, not the idea."}]},{type:"check",question:"What is survivorship bias?",options:["Seeing only the winners, which makes success look more common than it is","Businesses surviving a recession","Ranking sellers by their reviews"],answer:0},{type:"talk",text:"Reflect or talk with family: how much extra a month would actually make a difference, and how many hours a week can you honestly give it?"}],sources:[{title:"JPMorgan Chase Institute: Online Platform Economy 2018 findings",url:"https://www.jpmorganchase.com/institute/news-events/institute-2018-online-platform-economy-report-findings"},{title:"Linktree 2022 Creator Report (via Techdirt)",url:"https://www.techdirt.com/2022/05/13/the-internet-has-opened-up-the-creator-economy-to-new-heights/"},{title:"Etsy Q4 and full-year 2025 results",url:"https://investors.etsy.com/_assets/_fea57334fe81a735b34cf3bf4bdcb553/etsy/db/938/10062/earnings_release/Exhibit+99.1+12.31.2025.pdf"}]},{id:"b-five-honest-paths",title:"Five honest paths, compared",emoji:"\ud83d\udee4\ufe0f",cards:[{type:"read",text:"The common honest paths are selling handmade or resale goods, selling a service like bookkeeping or lawn care, affiliate links, content creation, and small digital products like templates."},{type:"read",text:"A service can pay from your very first client. Content and digital products usually need an audience first; YouTube, for example, requires 1,000 subscribers plus 4,000 watch hours in a year before you can even apply to earn ad money."},{type:"read",text:"Affiliate links pay small percentages. Amazon's standard rates run from 0% to 10%, with toys at 3%, so recommending a $50 toy earns about $1.50, and the commission goes to a person you know instead of a big ad network."},{type:"scenario",text:"You're an experienced bookkeeper with five spare hours a week. Which first move fits best?",choices:[{text:"Buy a $2,000 course on starting an online store.",best:!1,why:"Spending big on an unfamiliar model adds risk before you've earned anything."},{text:"Offer bookkeeping to two or three local small businesses.",best:!0,why:"Selling a skill you already have can bring in income soonest, with little upfront cost."},{text:"Start a video channel and wait for ad money.",best:!1,why:"Ad money needs a large audience, which can take years to build."}]},{type:"check",question:"At a 3% affiliate rate, recommending a $50 toy earns about:",options:["$15","$1.50","$5"],answer:1},{type:"talk",text:"With family, list each adult's skills and pick one path to test for 30 days."}],sources:[{title:"YouTube Partner Program eligibility",url:"https://support.google.com/youtube/answer/72851"},{title:"Amazon Associates commission rates (Lasso, checked Oct 2026)",url:"https://getlasso.co/amazon-affiliate-commission-rate/"}]},{id:"b-pricing-true-costs",title:"Pricing and true costs",emoji:"\ud83c\udff7\ufe0f",cards:[{type:"read",text:"A fair price covers materials, platform fees, shipping, packaging, your time and a margin. On Etsy alone that means $0.20 per listing, 6.5% of the sale including shipping, payment processing, and 12% to 15% more on orders that come from Etsy's offsite ads."},{type:"read",text:"Pay yourself for your time. If a $30 item takes two hours and $12 in materials and fees, you earned $9 an hour before taxes."},{type:"read",text:"The FTC warns that MLM income figures often leave out expenses. Any side business can fool you the same way, so count every cost from day one."},{type:"scenario",text:"Your candles sell for $20. Materials cost $6, fees $2.50 and shipping supplies $1.50, and each one takes 30 minutes. What do you earn per hour?",choices:[{text:"$40 an hour",best:!1,why:"That uses the sale price, not what's left after costs."},{text:"$20 an hour",best:!0,why:"$20 minus $10 in costs leaves $10 per half hour, about $20 an hour before taxes."},{text:"$10 an hour",best:!1,why:"That's the profit per candle, not per hour."}]},{type:"check",question:"Which of these is NOT a cost?",options:["Platform fees","Packaging","The price the customer pays"],answer:2},{type:"talk",text:"Pick one thing you could sell and price it out fully, including an hourly rate you'd be glad to earn."}],sources:[{title:"Etsy Fees & Payments Policy",url:"https://www.etsy.com/legal/fees/"},{title:"FTC Business Guidance Concerning Multi-Level Marketing",url:"https://www.ftc.gov/business-guidance/resources/business-guidance-concerning-multi-level-marketing"}]},{id:"b-taxes-and-records",title:"Taxes, sales tax and records",emoji:"\ud83d\uddc2\ufe0f",cards:[{type:"read",text:"All side income counts, form or no form. The IRS says you must report income whether or not you receive a Form 1099-K."},{type:"read",text:"Payment apps and marketplaces must send a 1099-K once you pass $20,000 and 200 transactions in a year, after a 2025 law reset the threshold; card payments are reported at any amount, and some states set lower limits."},{type:"read",text:"Once net self-employment earnings reach $400, you generally owe 15.3% self-employment tax for Social Security and Medicare on top of income tax. This isn't tax advice, so check IRS.gov or a tax professional."},{type:"read",text:"Sales tax depends on your state. Big marketplaces usually collect it on their sales, but in Texas, for example, sellers based in the state still need a sales tax permit and must file returns."},{type:"scenario",text:"You earned $3,000 pet sitting this year, paid through a payment app, and got no 1099-K. What's true?",choices:[{text:"No form means no tax.",best:!1,why:"The IRS says income is reportable with or without a form."},{text:"Report it, using your own records of what you earned and spent.",best:!0,why:"Good records let you report the right amount and deduct real costs."},{text:"Only report it once you pass $20,000.",best:!1,why:"$20,000 is when the app must send a form, not when income becomes taxable."}]},{type:"check",question:"At what level of net self-employment earnings does self-employment tax generally apply?",options:["$400","$20,000","$600"],answer:0},{type:"talk",text:"Talk with family about where receipts will live and how much of each payment you'll set aside for taxes."}],sources:[{title:"IRS: Understanding your Form 1099-K",url:"https://www.irs.gov/businesses/understanding-your-form-1099-k"},{title:"IRS: Self-employment tax",url:"https://www.irs.gov/businesses/small-businesses-self-employed/self-employment-tax-social-security-and-medicare-taxes"},{title:"Texas Comptroller: marketplace providers and sellers",url:"https://comptroller.texas.gov/taxes/sales/marketplace-providers-sellers.php"}]},{id:"b-disclose-it",title:"Disclose it: #ad and affiliate links",emoji:"\ud83d\udce3",cards:[{type:"read",text:"Under the FTC's Endorsement Guides, revised in 2023, you must clearly disclose any money, free product, family or business tie behind a recommendation. It has to be hard to miss: on screen and spoken in a video, and never only in a bio or among hashtags."},{type:"read",text:"For affiliate links, the FTC says 'affiliate link' alone isn't clear; something like 'I get commissions for purchases made through links in this post,' placed near the link, is."},{type:"read",text:"Fake reviews, and paying only for positive ones, are banned under an FTC rule in force since October 21, 2024, with penalties up to $51,744 per violation, adjusted for inflation. On OurDot, adults may share affiliate links, but never to or by anyone under 18."},{type:"scenario",text:"A friend's shop gives you a free stand mixer to review. What's the best post?",choices:[{text:"Rave about it without mentioning it was free.",best:!1,why:"A free product is a connection your readers deserve to know about."},{text:"Share your honest review and start with 'They sent me this mixer for free.'",best:!0,why:"A clear, upfront disclosure keeps trust and follows FTC guidance."},{text:"Add #ad to your bio once.",best:!1,why:"A bio disclosure is easy to miss, and the FTC says it doesn't count."}]},{type:"check",question:"Which affiliate disclosure is clearest?",options:["#aff","Affiliate link","I earn a commission if you buy through this link"],answer:2},{type:"talk",text:"Reflect: which of your recommendations would someone want to know you were paid for? Write the disclosure sentence you'll use every time."}],sources:[{title:"FTC: Endorsement Guides, What People Are Asking",url:"https://www.ftc.gov/business-guidance/resources/ftcs-endorsement-guides"},{title:"FTC: Disclosures 101 for Social Media Influencers",url:"https://www.ftc.gov/business-guidance/resources/disclosures-101-social-media-influencers"},{title:"Morgan Lewis: FTC final rule on consumer reviews",url:"https://www.morganlewis.com/pubs/2024/08/ftc-issues-final-rule-on-consumer-reviews-and-testimonials"}]},{id:"b-scams-mlms-passive-income",title:"Scams, MLMs and 'passive income' pitches",emoji:"\ud83d\udea9",cards:[{type:"read",text:"People told the FTC they lost $750.6 million to business and job opportunity scams in 2024, and losses to job scams alone rose from $90 million in 2020 to $501 million."},{type:"read",text:"The FTC says most people who join MLMs and work hard make little or no money. Its staff's 2024 review of 70 MLM income reports found most participants made $1,000 a year or less, often before expenses, and a 2018 AARP Foundation study found nearly half of participants lost money."},{type:"read",text:"'AI-powered' online store programs are the newer version. In 2024 the FTC sued several that promised passive income; one, Ascend Ecom, was tied to at least $25 million in losses."},{type:"scenario",text:"A cousin invites you into a 'wellness business': a $299 starter kit, a monthly order to stay active, and bonuses for recruits. What's the best response?",choices:[{text:"Join to support them.",best:!1,why:"Required monthly buying and recruit bonuses are FTC warning signs, and you can support your cousin in other ways."},{text:"Ask for the income disclosure and what share earn over $1,000 after expenses, then kindly decline if it's unclear.",best:!0,why:"Asking for typical results after costs is what the FTC suggests, and kindness protects the relationship."},{text:"Join and recruit three friends fast to earn back the $299.",best:!1,why:"Recruiting to cover your costs is how losses spread to friends."}]},{type:"check",question:"Under the FTC Business Opportunity Rule, how long before you pay must a covered seller give you its disclosure document?",options:["24 hours","7 days","30 days"],answer:1},{type:"talk",text:"With family, agree on a house rule: no paying to start any 'opportunity' until we've waited a week and looked up complaints together."}],sources:[{title:"FTC: reported fraud losses jump to $12.5 billion in 2024",url:"https://www.ftc.gov/news-events/news/press-releases/2025/03/new-ftc-data-show-big-jump-reported-losses-fraud-125-billion-2024"},{title:"FTC staff report analyzes 70 MLM income disclosure statements",url:"https://search.ftc.gov/business-guidance/blog/2024/09/ftc-staff-report-analyzes-70-mlm-income-disclosure-statements"},{title:"FTC: Operation AI Comply",url:"https://www.ftc.gov/news-events/news/press-releases/2024/09/ftc-announces-crackdown-deceptive-ai-claims-schemes"}]},{id:"b-paying-for-education",title:"Paying for courses or mentors, wisely",emoji:"\ud83c\udf93",cards:[{type:"read",text:"Start free: IRS and FTC guides cover the rules, and SCORE offers free volunteer business mentoring through the SBA. Pay only when you can name the exact skill you're missing and the teacher has a checkable record in it."},{type:"read",text:"Ask for typical results, not the best ones. The FTC says earnings claims should reflect what typical participants earn after expenses, and a 'results not typical' line doesn't fix a misleading claim."},{type:"read",text:"Red flags: income screenshots, mansions and sports cars (the FTC treats these as implied earnings claims), countdown timers, upsell 'inner circles' and refund terms you can't find. The FTC's proposed earnings-claim rule was still pending in 2026, so don't count on it to protect you yet."},{type:"scenario",text:"A coach offers a $3,500 program, poses with a sports car, and says spots close tonight. What's the best move?",choices:[{text:"Pay now to lock in a spot.",best:!1,why:"Deadline pressure is designed to stop you from checking."},{text:"Ask what share of past students earned back the fee, get the refund policy in writing, talk to references, and wait a week.",best:!0,why:"Honest teachers can share typical results and won't mind you taking time."},{text:"Put it on a credit card, since it'll pay for itself.",best:!1,why:"Borrowing for a promise adds debt on top of the risk."}]},{type:"check",question:"How does the FTC treat luxury lifestyle images in a money-making pitch?",options:["As harmless decoration","As possible implied earnings claims","As proof the program works"],answer:1},{type:"talk",text:"Reflect: what one specific skill would help you most right now, and what free source could you try first?"}],sources:[{title:"SBA: SCORE business mentoring",url:"https://www.sba.gov/local-assistance/resource-partners/score-business-mentoring"},{title:"FTC Business Guidance Concerning Multi-Level Marketing",url:"https://www.ftc.gov/business-guidance/resources/business-guidance-concerning-multi-level-marketing"},{title:"ABA: FTC financial deception enforcement and rulemaking",url:"https://www.americanbar.org/groups/antitrust_law/resources/newsletters/ftc-financial-deception-enforcement-rulemaking/"}]},{id:"b-kids-in-your-business",title:"Kids in your business: a guardian's duties",emoji:"\ud83e\udd1d",cards:[{type:"read",text:"Federal child labor law sets 14 as the minimum age for most jobs, but kids of any age may work in a non-hazardous business their own family owns, babysit, or perform in media. Where state law is stricter, it wins."},{type:"read",text:"If your content features a child and earns money, several states now require a share to be saved in a trust for them, including Illinois (2024), California (2025, 65% of the child's proportional share), Minnesota (2025) and Utah (2025). Minnesota bars children under 14 from content creation work altogether."},{type:"read",text:"COPPA can apply to the owner of a kid-directed channel that collects viewer data, as the FTC warned after YouTube paid $170 million in 2019. Minors usually can't be held to contracts, so a guardian must handle every deal."},{type:"scenario",text:"Your 11-year-old's craft videos start earning money. What's the best setup?",choices:[{text:"Let them run their own account and talk with brands.",best:!1,why:"YouTube requires users to be 13, and kids shouldn't negotiate with companies alone."},{text:"Run it from a guardian's account, check your state's rules, save their share in an account in their name, and give them a veto on every video.",best:!0,why:"This follows platform rules, protects the child's earnings and gives them a real say."},{text:"Use the earnings for the household, since you do the filming.",best:!1,why:"Several states now require a set-aside for the child, and it's their work too."}]},{type:"check",question:"In Minnesota, what can a person 13 or older ask for about videos featuring them?",options:["A bigger share of ad money","Deletion of content showing their likeness","A sponsorship deal"],answer:1},{type:"talk",text:"Talk as a family: what will we never film or share, even if it would earn money? Let the kids answer first."}],sources:[{title:"U.S. Dept. of Labor elaws: child labor FAQ",url:"https://webapps.dol.gov/elaws/faq/esa/flsa/026.htm"},{title:"Minnesota Statutes 181A.13",url:"https://www.revisor.mn.gov/statutes/cite/181A.13"},{title:"FTC: YouTube channel owners, is your content directed to children?",url:"https://www.ftc.gov/business-guidance/blog/2019/11/youtube-channel-owners-your-content-directed-children"}]}]}]}},1124,[]);
